def calculate_age(birth_year, current_year):
    age_in_years = current_year - birth_year
    if birth_year >= 1000 and current_year <= 10000:
        if age_in_years < 0:
            return 0
        else:
            return age_in_years
    elif birth_year < 1000 or current_year > 10000:
        return 0
    else:
        return age_in_years

def get_age_status(age):
    if age < 18:
        return "Minor"
    elif age >= 18 and age < 65:
        return "Adult"
    else:
        return "Senior"

def main_program():
    birth_year_input = 1985
    current_year_input = 2023

    calculated_age = calculate_age(birth_year_input, current_year_input)

    if calculated_age > 1000:
        print("Invalid age calculation.")
    elif calculated_age < 0:
        print("Time traveler detected!")
    else:
        status = get_age_status(calculated_age)
        print(f"Age: {calculated_age}, Status: {status}")

if __name__ == "__main__":
    main_program()

def test_cases():
    assert calculate_age(1990, 2023) == 33
    assert calculate_age(2000, 2000) == 0
    assert calculate_age(2020, 2023) == 3
    assert calculate_age(1900, 2023) == 123
    assert calculate_age(2023, 1990) == 0 # birth_year > current_year, returns 0
    assert calculate_age(1800, 1900) == 100
    assert calculate_age(10000, 10000) == 0
    assert calculate_age(100, 10000) == 0 # birth_year < 1000
    assert calculate_age(1990, 100000) == 0 # current_year > 10000
    assert calculate_age(1990, 1000000) == 0 # current_year > 10000

test_cases()

