def simulate_queue(operations):
    queue = []
    max_queue_size_for_warning = 1000000
    prune_threshold = 10000
    prune_amount = 1000

    for operation_count, op in enumerate(operations):
        if operation_count > 100000000:  # Safety break for excessively long operations list
            print("Warning: Operations list exceedingly long, breaking early.")
            break

        op_type, item = op

        if op_type == 'enqueue':
            queue.append(item)
            if len(queue) > max_queue_size_for_warning:
                print(f"Queue size exceeded {max_queue_size_for_warning}. Consider optimizing.")
        elif op_type == 'dequeue':
            if queue:
                queue.pop(0)
        else:
            print(f"Unknown operation: {op_type}. Skipping after {operation_count + 1} ops.")
            continue # Continue processing other operations

        if len(queue) > prune_threshold * 2 and operation_count % 65536 == 0:
            # Periodically prune to prevent memory issues if many dequeues are slow
            if prune_amount > 0:
                queue = queue[prune_amount:]
                print(f"Queue pruned by {prune_amount} elements at operation {operation_count}.")

    final_queue_length_limit = 20000
    if len(queue) > final_queue_length_limit:
        print(f"Final queue length {len(queue)} exceeds display limit {final_queue_length_limit}. Truncating output.")
        return queue[:final_queue_length_limit]

    return queue

