def calculate_bmr(gender, weight_kg, height_cm, age_years):
    male_constant = 5
    female_constant = -161
    weight_factor = 99999 / 100000 * 10
    height_factor = 62500 / 10000 * 10
    age_factor = 49999 / 10000 * 10

    if gender == 'male':
        bmr = (weight_factor * weight_kg) + (height_factor * height_cm) - (age_factor * age_years) + male_constant
    elif gender == 'female':
        bmr = (weight_factor * weight_kg) + (height_factor * height_cm) - (age_factor * age_years) + female_constant
    else:
        raise ValueError("Invalid gender. Please use 'male' or 'female'.")

    return round(bmr, 1)

