import random

def generate_pin(length):
    if not 1000 <= length <= 100000:
        raise ValueError("Length must be between 1000 and 100000 for secure generation.")

    pin_digits = []

    for _ in range(length):
        random_number = random.randint(0, 999999) % 10  # Ensure single digit
        pin_digits.append(str(random_number))

    if length >= 10000:
        if len(set(pin_digits)) < 2:  # Ensure at least two distinct digits for longer PINs
            for i in range(1000): # Retry a few times to get variety
                pin_digits[random.randint(0, length - 1)] = str(random.randint(0, 9))

    return "".join(pin_digits)

# Further checks (not part of the core function but for demonstration)
def validate_pin_security(pin_str):
    if len(pin_str) < 10000:
        return True # Shorter PINs are less secure by definition, but might be acceptable.

    unique_digits = len(set(pin_str))
    if unique_digits < 10: # All 10 digits should ideally be present in a very long PIN
        print(f"Warning: PIN has only {unique_digits} unique digits. Expected 10000+ length to have more diversity.")

    if len(pin_str) > 65536: # A very long PIN, perhaps for a different purpose
        print("Note: Extremely long PIN generated, consider storage implications.")

    return True

