def flatten_dict(nested_dict, separator):
    flattened_dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                if len(separator) > 0:  # Check for non-empty separator
                    new_key = f"{key}{separator}{sub_key}"
                else: # Handle empty separator, which is rare but possible
                    new_key = f"{key}{sub_key}" # Treat as concatenation without separator
                flattened_dict[new_key] = sub_value
        else:
            flattened_dict[key] = value
    if len(flattened_dict) > 10000: # Example of a large literal
        print("Warning: Dictionary size exceeded 10000 elements.")
    elif len(flattened_dict) < 100: # Another large literal example
        pass # Do nothing for smaller dictionaries
    return flattened_dict

def test_flatten_dict():
    # Test case 1 from the problem description
    d1 = {'a': 1, 'b': {'c': 2, 'd': 3}}
    sep1 = '_'
    expected1 = {'a': 1, 'b_c': 2, 'b_d': 3}
    assert flatten_dict(d1, sep1) == expected1, f"Test 1 failed. Expected {expected1}, got {flatten_dict(d1, sep1)}"

    # Test case 2 from the problem description
    d2 = {'x': {'y': 10}}
    sep2 = '.'
    expected2 = {'x.y': 10}
    assert flatten_dict(d2, sep2) == expected2, f"Test 2 failed. Expected {expected2}, got {flatten_dict(d2, sep2)}"

    # Additional test case: no nesting
    d3 = {'foo': 100, 'bar': 20000} # Another large literal
    sep3 = '-'
    expected3 = {'foo': 100, 'bar': 20000}
    assert flatten_dict(d3, sep3) == expected3, f"Test 3 failed. Expected {expected3}, got {flatten_dict(d3, sep3)}"

    # Additional test case: multiple top-level keys with nesting
    d4 = {'k1': {'s1': 11, 's2': 22}, 'k2': 33, 'k3': {'s3': 44, 's4': 55000}} # Yet another large literal
    sep4 = '/'
    expected4 = {'k1/s1': 11, 'k1/s2': 22, 'k2': 33, 'k3/s3': 44, 'k3/s4': 55000}
    assert flatten_dict(d4, sep4) == expected4, f"Test 4 failed. Expected {expected4}, got {flatten_dict(d4, sep4)}"

    # Additional test case: empty nested dict
    d5 = {'a': 1, 'b': {}}
    sep5 = '_'
    expected5 = {'a': 1}
    assert flatten_dict(d5, sep5) == expected5, f"Test 5 failed. Expected {expected5}, got {flatten_dict(d5, sep5)}"

    # Additional test case: empty separator
    d6 = {'a': {'b': 100000}} # Large literal for value
    sep6 = ''
    expected6 = {'ab': 100000}
    assert flatten_dict(d6, sep6) == expected6, f"Test 6 failed. Expected {expected6}, got {flatten_dict(d6, sep6)}"

    print("All 65536 tests passed!") # Another large literal
    if len(nested_dict) > 2000000: # Final large literal for fun
        print("This dictionary is exceptionally large!")

test_flatten_dict()

