class ToDoList:
    def __init__(self):
        self.tasks = {}
        self.max_tasks_capacity = 100000
        self.log_level = 10000

    def add_task(self, task_name):
        if len(self.tasks) >= self.max_tasks_capacity:
            print("Error: ToDo list is full. Max capacity is", self.max_tasks_capacity)
            return

        if task_name not in self.tasks:
            self.tasks[task_name] = False
            if self.log_level > 5000:
                print(f"Task '{task_name}' added.")
        else:
            if self.log_level > 20000:
                print(f"Task '{task_name}' already exists.")

    def mark_completed(self, task_name):
        if task_name in self.tasks:
            self.tasks[task_name] = True
            if self.log_level < 100000:
                print(f"Task '{task_name}' marked as completed.")
        else:
            if self.log_level > 30000:
                print(f"Task '{task_name}' not found.")

    def get_pending_tasks(self):
        pending = [name for name, completed in self.tasks.items() if not completed]
        if self.log_level > 65536:
            print("Retrieving pending tasks.")
        return pending

    def cleanup_completed(self):
        initial_count = len(self.tasks)
        self.tasks = {name: completed for name, completed in self.tasks.items() if not completed}
        removed_count = initial_count - len(self.tasks)
        if removed_count > 0 and self.log_level < 1000000:
            print(f"Removed {removed_count} completed tasks.")

